function bindMascot(){const button=$('#buddy');if(!button)return;let count=0;const lines=['¡Guau! ¿Qué descubrimos hoy?','Una pista a la vez. Tú puedes.','Documenta el camino, no solo la flag.','Buen writeup. Mejor con una portada.'];button.onclick=()=>{button.classList.remove('greet');void button.offsetWidth;button.classList.add('greet');$('#buddy-speech').textContent=lines[count++%lines.length];};button.addEventListener('animationend',()=>button.classList.remove('greet'));}
function bindCoverEditor(){const picker=$('#cover-file');$('#choose-cover').onclick=()=>picker.click();$('#cover-alt').oninput=saveForm;$('#remove-cover')?.addEventListener('click',()=>{saveForm();current.cover='';current.coverAlt='';persist();editor();});picker.onchange=async()=>{const file=picker.files[0];if(!file)return;const draft=current,button=$('#choose-cover');button.disabled=true;button.textContent='Preparando imagen…';try{const image=await prepareCover(file);draft.cover=image;const ok=persist();if(current===draft&&location.hash.startsWith('#/editor'))editor();if(ok)toast('Portada añadida al borrador. Se subirá al publicar.');}catch(error){toast(error.message);}finally{if(button.isConnected){button.disabled=false;button.textContent='Cambiar portada';}picker.value='';}};}
